INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(26001, 'Acts 7:12', 'Acts', 7, 12, '&nbsp;خو کله چې يعقوب واورېدل چې هلته په مِصر کښې غله شته نو هغۀ زمونږ پلار نيکونه په اول ځل هلته ولېږل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26002, 'Acts 7:13', 'Acts', 7, 13, '&nbsp;په دوباره تللو يوسف خپلو وروڼو ته خپل ځان څرګند کړو او فِرعون ته د يوسف د خاندان په حقله پته ولګېده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26003, 'Acts 7:14', 'Acts', 7, 14, '&nbsp;د دې نه وروستو يوسف خپل پلار يعقوب او خپلو ټولو رشته‌دارانو ته چې په شمېر کښې ټول پينځۀ اويا کسان وُو، مِصر ته د راتلو بلنه ورکړله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26004, 'Acts 7:15', 'Acts', 7, 15, '&nbsp;نو يعقوب مِصر ته لاړو، هم هلته زمونږ د پلار نيکونو سره وفات شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26005, 'Acts 7:16', 'Acts', 7, 16, '&nbsp;د هغوئ لاشونه واپس شِکم ته راوړلے شول او په هغه قبرستان کښې ښخ کړے شول، کوم چې اِبراهيم د بنى همور نه په شِکم کښې په بيعه اخستے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26006, 'Acts 7:17', 'Acts', 7, 17, '&nbsp;خو چې د اِبراهيم سره د خُدائ پاک د خپلې وعدې د پوره کېدو وخت رانزدې شو نو په مِصر کښې زمونږ د قوم شمېر ډېر زيات شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26007, 'Acts 7:18', 'Acts', 7, 18, '&nbsp;بيا دا چې په مِصر کښې يو بل بادشاه په تخت کښېناستو څوک چې د يوسف نه ناخبره وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26008, 'Acts 7:19', 'Acts', 7, 19, '&nbsp;هغۀ زمونږ د قوم سره ټګى وکړه او زمونږ پلار نيکونه يې په ظلم دې ته مجبوره کړل چې هغوئ خپل د پيو ماشومان بهر وغورزوى چې مړۀ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26009, 'Acts 7:20', 'Acts', 7, 20, '&nbsp;هم په دغه وخت موسىٰ پېدا شو. او هغه د خُدائ پاک نيازبين وو او تر درېو مياشتو پورې هغه د خپل پلار په کور کښې وساتلے شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26010, 'Acts 7:21', 'Acts', 7, 21, '&nbsp;او کله چې هغه بهر وغورزولے شو نو د فِرعون لور په خپله هغه راوچت کړو او د خپل زوئ په شان يې لوئ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26011, 'Acts 7:22', 'Acts', 7, 22, '&nbsp;نو موسىٰ د مِصريانو د ټول حکمت او پوهې تعليم حاصل کړو او هغه په کارونو او کلام کښې ښۀ قابل شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26012, 'Acts 7:23', 'Acts', 7, 23, '&nbsp;کله چې هغه د څلوېښتو کالو شو، نو د هغۀ په زړۀ کښې دا خيال راغلو چې هغه د خپلو رشته‌دارو بنى اِسرائيلو سره مِلاوېدو له لاړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26013, 'Acts 7:24', 'Acts', 7, 24, '&nbsp;هغۀ وکتل چې يو مِصرى د يو بنى اِسرائيلى سره ظلم کولو نو موسىٰ د هغۀ د مدد دپاره په منډه ورغلو او د هغۀ بدل يې ترې واخستو او مړ يې کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26014, 'Acts 7:25', 'Acts', 7, 25, '&nbsp;د موسىٰ خيال وو چې د دۀ خپل خلق به پوهه شى چې خُدائ پاک هغه د دوئ د خلاصون دپاره استعمالوى، خو هغوئ پوهه نۀ شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26015, 'Acts 7:26', 'Acts', 7, 26, '&nbsp;بله ورځ موسىٰ دوه کسان وليدل چې په جنګ وو، هغۀ د هغوئ د جګړې د ختمولو کوشش وکړو. موسىٰ ورته ووئيل چې، ”دا ولې؟ تاسو خو وروڼه يئ، نو تاسو ولې يو بل وهئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26016, 'Acts 7:27', 'Acts', 7, 27, '&nbsp;خو کوم سړى چې د هغه بل سره ظلم کولو موسىٰ له يې ديکه ورکړه او وې وئيل چې، ”تۀ چا په مونږ حاکِم او منصف جوړ کړے يې؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26017, 'Acts 7:28', 'Acts', 7, 28, '&nbsp;ولې تۀ ما هم لکه د پرونى مِصرى په شان وژل غواړې څۀ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26018, 'Acts 7:29', 'Acts', 7, 29, '&nbsp;کله چې موسىٰ دا واورېدل نو ميديان ته وتښتېدو او هغه هلته د مسافرو غوندې اوسېدو او هم هلته خُدائ پاک دوه زامن ورکړل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26019, 'Acts 7:30', 'Acts', 7, 30, '&nbsp;د څلوېښت کاله تېرېدو نه وروستو يوه فرښته د سينا غرۀ سره نزدې په صحرا کښې د سوزېدونکى بوټى په لمبو کښې موسىٰ ته راښکاره شوه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26020, 'Acts 7:31', 'Acts', 7, 31, '&nbsp;کله چې هغۀ دا وليدل نو هغه په دې ليدو حېران شو. او څنګه چې هغه د نزدې ليدلو دپاره ورغلو نو هغۀ د مالِک آواز واورېدو چې،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26021, 'Acts 7:32', 'Acts', 7, 32, '&nbsp;”زۀ ستا د پلار نيکونو خُدائ پاک يم، د اِبراهيم او د اِسحاق او د يعقوب خُدائ پاک يم.“ او موسىٰ د يرې نه په رپېدو شو او ورته يې د کتلو جرأت نۀ شو کولے.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26022, 'Acts 7:33', 'Acts', 7, 33, '&nbsp;بيا مالِک خُدائ ورته وفرمائيل ”نور نزدې مۀ راځه. پېزار وباسه، ځکه چې تۀ په پاکه زمکه ولاړ يې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26023, 'Acts 7:34', 'Acts', 7, 34, '&nbsp;ما وليدل چې زما د خلقو سره په مِصر کښې څومره ظلم کيږى، ما د هغوئ فرياد اورېدلے دے او زۀ راغلم چې هغوئ له خلاصون ورکړم. اوس راځه چې زۀ تا واپس مِصر ته ولېږم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26024, 'Acts 7:35', 'Acts', 7, 35, '&nbsp;دا هغه موسىٰ دے چې هغوئ په دې ټکو رد کړے وو چې تۀ چا زمونږ حاکِم او منصف جوړ کړے يې؟ د هغه فرښتې په وسيله چې هغۀ ته په بوټى کښې ښکاره شوې وه هم هغه خُدائ پاک په خپله موسىٰ د هغوئ د حاکِم او خلاصوونکى په توګه راولېږلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26025, 'Acts 7:36', 'Acts', 7, 36, '&nbsp;هغۀ هغوئ د مِصر نه وويستل او بيا يې په مِصر او بحرِقُلزم او په صحرا کښې تر څلوېښتو کالو پورې ډېر عجيبه کارونه او معجزې وښودلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26026, 'Acts 7:37', 'Acts', 7, 37, '&nbsp;دا هغه موسىٰ دے چې بنى اِسرائيلو ته يې وفرمائيل، ”خو خُدائ پاک به تاسو ته زما په شان يو پېغمبر راولېږى چې هغه به ستاسو د خپلو خلقو نه وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26027, 'Acts 7:38', 'Acts', 7, 38, '&nbsp;موسىٰ په صحرا کښې زمونږ د پلار نيکونو سره په يوه غونډه کښې وو چې په هم هغه وخت هغه فرښتې ورسره خبرې کولې چې د سينا په غرۀ کښې دۀ سره وه هغې مونږ ته د رارسولو دپاره هغۀ ته ژوندے کلام ورکړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26028, 'Acts 7:39', 'Acts', 7, 39, '&nbsp;خو زمونږ پلار نيکونو د هغۀ مشرى ونۀ منله. هغوئ هغه رد کړو او د هغوئ زړۀ وو چې مِصر ته واپس لاړ شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26029, 'Acts 7:40', 'Acts', 7, 40, '&nbsp;هغوئ هارون ته ووئيل چې، ”مونږ له داسې معبودان جوړ کړه چې زمونږ لارښودنه کوى. ځکه کوم موسىٰ چې مونږ د مِصر نه راوويستلو، مونږ ته دا پته نشته چې په هغۀ څۀ چل وشو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26030, 'Acts 7:41', 'Acts', 7, 41, '&nbsp;نو هغه وخت هغوئ د سخى په شکل يو بُت جوړ کړو او هغه بُت ته يې قربانى وکړه او په خپلو لاسونو جوړ شوى څيز ته يې خوشحالى کوله.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26031, 'Acts 7:42', 'Acts', 7, 42, '&nbsp;خو په داسې کولو خُدائ پاک د هغوئ نه نارضا شو او هغوئ يې پرېښودل چې د آسمان د ستورو عبادت وکړى لکه څنګه چې د نبيانو په کِتاب کښې ليکلى دى چې، ”اے بنى اِسرائيلو کله چې تاسو د څلوېښتو کالو دپاره په بيابان کښې وئ نو ما ته مو کله قربانۍ او نذرانې راوړى دى څۀ؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26032, 'Acts 7:43', 'Acts', 7, 43, '&nbsp;خو تاسو خپل ځان سره نور معبودان د مولک زيارت او د رفان خُدائ ستورى او تصويرونه د عبادت کولو دپاره يوړل، نو په دې وجه به زۀ تاسو د بابل نه بل خوا جلاوطن کړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26033, 'Acts 7:44', 'Acts', 7, 44, '&nbsp;زمونږ د پلار نيکونو سره په صحرا کښې د ګواهۍ خېمه وه، او موسىٰ دا د خُدائ پاک په حکم د هغه نقشې په مطابق جوړه کړه کومه چې هغۀ ته ښودلے شوې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26034, 'Acts 7:45', 'Acts', 7, 45, '&nbsp;زمونږ پلار نيکونو د يشوَع سره هغه خېمه راوړه، کله چې هغوئ د هغه قومونو په مُلک قبضه وکړه کوم چې خُدائ پاک د هغوئ نه مخکښې وويستل. دا خېمه په هغه مُلک کښې د داؤد تر وخته پورې وه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26035, 'Acts 7:46', 'Acts', 7, 46, '&nbsp;د داؤد نه خُدائ رضا وو او هغۀ د خُدائ نه دا سوال وکړو چې ما ته د يعقوب د خُدائ پاک د دائمى اوسېدو دپاره ځائ راکړه.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26036, 'Acts 7:47', 'Acts', 7, 47, '&nbsp;خو د دې باوجود سليمان د هغۀ دپاره کور جوړ کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26037, 'Acts 7:48', 'Acts', 7, 48, '&nbsp;اګر کۀ خُدائ تعالىٰ د انسان په لاس جوړ شوې کور کښې نۀ اوسى، لکه څنګه چې نبى اِشاره کړې ده،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26038, 'Acts 7:49', 'Acts', 7, 49, '&nbsp;مالِک خُدائ فرمائى چې ”آسمان زما تخت دے او زمکه زما د پښو چوکۍ ده. نو بيا هغه کور چرته دے چې تاسو يې زما دپاره جوړَوئ؟ هغه ځائ کوم دے چرته به چې زۀ آرام کوم؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26039, 'Acts 7:50', 'Acts', 7, 50, '&nbsp;دا هر څۀ ما په خپلو لاسونو نۀ دى جوړ کړى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26040, 'Acts 7:51', 'Acts', 7, 51, '&nbsp;تاسو باغيان يئ. ستاسو زړونه کافر شوى دى او رښتياو ته کاڼۀ يئ. تاسو لکه د خپل پلار نيکونو همېشه د روحُ القُدس مخالفت کوئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26041, 'Acts 7:52', 'Acts', 7, 52, '&nbsp;داسې يو نبى شته چې ستاسو پلار نيکونو نۀ وى زورَولے؟ هغوئ خو هغه نبيان هم ووژل چا چې د صادق د راتلو پېشګوئې کړې وه. او اوس تاسو د هغۀ مُخبرى وکړه او مړ مو کړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26042, 'Acts 7:53', 'Acts', 7, 53, '&nbsp;تاسو ته د فرښتو په وسيله شريعت درکړے شو خو تاسو پرې عمل ونۀ کړو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26043, 'Acts 7:54', 'Acts', 7, 54, '&nbsp;کله چې هغوئ دا واورېدل نو هغوئ ډېر غصه شول او ستِفانوس ته يې غاښونه چيچل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26044, 'Acts 7:55', 'Acts', 7, 55, '&nbsp;خو ستِفانوس د روحُ القُدس نه معمور وو، هغۀ بره آسمان ته وکتل او د خُدائ پاک جلال يې وليدو او عيسىٰ يې وليدو چې د خُدائ پاک ښى لاس ته ولاړ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26045, 'Acts 7:56', 'Acts', 7, 56, '&nbsp;هغۀ ووئيل چې، ”وګورئ، ما ته آسمان پرانستے ښکارى او اِبن آدم د خُدائ پاک ښى لاس ته ولاړ دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26046, 'Acts 7:57', 'Acts', 7, 57, '&nbsp;په دې خبره هغوئ په زوره چغې کړې او خپل غوږونه يې بند کړل. او هغوئ ټولو په هغۀ ورمنډه کړه،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26047, 'Acts 7:58', 'Acts', 7, 58, '&nbsp;بيا يې هغه د ښار نه بهر وويستو او سنګسار يې کړو. او ګواهانو خپلې جامې د ساؤل نومې يو ځوان سړى په پښو کښې کېښودلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(26048, 'Acts 7:59', 'Acts', 7, 59, '&nbsp;کله چې هغوئ ستِفانوس سنګسارولو نو ستِفانوس دُعا وکړه چې، ”اے مالِکه عيسىٰ، زما روح قبول کړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
